<?php
get_header();
$page = max( 1, (int) get_query_var( 'paged' ), (int) get_query_var( 'page' ) );
$news = new WP_Query( array( 'post_type'=>'post', 'post_status'=>'publish', 'posts_per_page'=>10, 'paged'=>$page, 'ignore_sticky_posts'=>true ) );
?>
<header class="gmr-news-head"><div class="gmr-wrap"><span class="gmr-kicker">Actualidad de la galería</span><div class="gmr-news-head__layout"><h1>Noticias<br>y conversaciones</h1><p>Exposiciones, artistas, procesos y noticias que dan forma a la vida cultural de Galería Mayarí Rojas.</p></div></div></header>
<section class="gmr-news-list"><div class="gmr-wrap"><?php if ( $news->have_posts() ) : $news->the_post(); ?><article class="gmr-news-feature"><a href="<?php the_permalink(); ?>" class="gmr-news-feature__media"><?php if ( has_post_thumbnail() ) : the_post_thumbnail( 'large' ); else : ?><span>Galería Mayarí Rojas</span><?php endif; ?></a><div class="gmr-news-feature__copy"><div class="gmr-news-meta"><span><?php echo wp_kses_post( get_the_category_list( ' · ' ) ?: 'Noticias' ); ?></span><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>"><?php echo esc_html( get_the_date( 'j F, Y' ) ); ?></time></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php if ( has_excerpt() ) : ?><p><?php echo esc_html( get_the_excerpt() ); ?></p><?php endif; ?><a class="gmr-news-link" href="<?php the_permalink(); ?>">Leer noticia <span aria-hidden="true">↗</span></a></div></article><div class="gmr-news-grid"><?php while ( $news->have_posts() ) : $news->the_post(); ?><article class="gmr-news-card"><a class="gmr-news-card__media" href="<?php the_permalink(); ?>"><?php if ( has_post_thumbnail() ) : the_post_thumbnail( 'medium_large' ); else : ?><span>Galería Mayarí Rojas</span><?php endif; ?></a><div class="gmr-news-card__copy"><div class="gmr-news-meta"><span><?php echo wp_kses_post( get_the_category_list( ' · ' ) ?: 'Noticias' ); ?></span><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>"><?php echo esc_html( get_the_date( 'j M Y' ) ); ?></time></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php if ( has_excerpt() ) : ?><p><?php echo esc_html( get_the_excerpt() ); ?></p><?php endif; ?></div></article><?php endwhile; ?></div><?php if ( $news->max_num_pages > 1 ) : ?><nav class="gmr-news-pagination" aria-label="Paginación de noticias"><?php echo paginate_links( array( 'total'=>$news->max_num_pages, 'current'=>$page, 'type'=>'list', 'prev_text'=>'← Anteriores', 'next_text'=>'Siguientes →' ) ); ?></nav><?php endif; ?><?php else : ?><p class="gmr-empty">El archivo de noticias se encuentra en preparación.</p><?php endif; wp_reset_postdata(); ?></div></section>
<?php get_footer(); ?>
